      SUBROUTINE RCOUT1CC     PRINTS FIRST-ORDER TRANSFER MATRIXCC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'COCOM.CIN'      INCLUDE 'COP.CIN'      INCLUDE 'DATA1C.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM13A.CIN'      INCLUDE 'ELM13B.CIN'      INCLUDE 'ELM13C.CIN'      INCLUDE 'ELM15B.CIN'      INCLUDE 'ELM15C.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'RS.CIN'CC     LOCAL VARIABLESC      CHARACTER*1     BLANK      CHARACTER*8     LABOUT      INTEGER         IROW(10), ICOL(10)      REAL            OUTPUT(10)      DATA            BLANK /' '/      DATA IROW       /1,1,2,2,3,3,4,4,1,2/      DATA ICOL       /1,2,1,2,3,4,3,4,6,6/C---------------------------------------------------------------------C      IF (CDB .EQ. 6) THEN        LABOUT = BLANK      ELSE          LABOUT = LABEL(NUM)(1:8)      ENDIFC      IF (TERSE) GO TO 150      NCOLS = 6      IF (CDB .EQ. 14) THEN        WRITE (NOUT,1002) 1002   FORMAT (1H0,8X,'*ELEMENT MATRIX*')        GO TO 110      ENDIF      IF (CDB .EQ. 4 .OR. CDB .EQ. 6) NR = 1      IF (CDB .EQ. 24) NR = 2      IF (CDB .EQ. -4) NR = -1      IF (SOFA) THEN        IF (NORD3 .LT. 1) NCOLS = 1        IF (NORD3 .GE. 1) NCOLS = 7        WRITE (NOUT,1008) NR, LABOUT      ELSE        WRITE (NOUT,1004) NR, LABOUT      ENDIF 1004 FORMAT (1H ,8X,'*TRANSFORM',I2,1H*,2X,A8) 1008 FORMAT (1H ,8X,'*TRANSFORM',I2,1H*,2X,A8,65X,3HREF)C  110 DO 130 J = 1, 6      IF (SOFA) OUTPUT(NCOLS) = CO(J)/UBEAM(J)      IF (NORD3 .LT. 1) THEN        IF (NARROW) THEN          WRITE (NOUT,1005) OUTPUT(1)        ELSE          WRITE (NOUT,1015) OUTPUT(1)        ENDIF      ELSE        DO 125 K = 1, 6        OUTPUT(K) = RS(J,K)*UBEAM(K)/UBEAM(J)  125   CONTINUE        IF (NARROW) THEN          WRITE (NOUT,1006) (OUTPUT(K), K = 1, NCOLS)        ELSE          WRITE (NOUT,1003) (OUTPUT(K), K = 1, NCOLS)        ENDIF      ENDIF  130 CONTINUE 1005 FORMAT (66X,F13.5) 1015 FORMAT (86X,F15.5) 1006 FORMAT (F14.5,5F10.5,2X,F13.5) 1003 FORMAT (F21.5,5F10.5,15X,F15.5)      GO TO 200CC     SINGLE LINE OUTPUTC  150 DO 160 J = 1, 10      IR = IROW(J)      IC = ICOL(J)      OUTPUT(J) = RS(IR,IC)*UBEAM(IC)/UBEAM(IR)  160 CONTINUE      IF (.NOT. NARROW) THEN        IF (.NOT. LCPR) THEN          ALONG = LC/UFLOOR(1)          WRITE (NOUT,1000) ALONG, XFLOOR(1), LABOUT, OUTPUT 1000     FORMAT (1H ,8X,F10.3,1X,A4,2X,A6,3X,4F9.4,4X,4F9.4,4X,     1            2F9.4)        ELSE          WRITE (NOUT,1001) LABOUT, OUTPUT 1001     FORMAT (1H ,25X,A6,3X,4F9.4,4X,4F9.4,4X,2F9.4)        ENDIF      ELSE        IF (.NOT. LCPR) THEN          ALONG = LC/UFLOOR(1)          WRITE (NOUT,1007) ALONG, XFLOOR(1), LABOUT, OUTPUT(1),      1                      OUTPUT(2), OUTPUT(5), OUTPUT(6), OUTPUT(9) 1007     FORMAT (1H ,8X,F10.3,1X,A4,2X,A6,3X,5F9.4)        ELSE          WRITE (NOUT,1009) OUTPUT(1), OUTPUT(2), OUTPUT(5),      1                      OUTPUT(6), OUTPUT(9) 1009     FORMAT (1H ,25X,A6,3X,5F9.4)        ENDIF       ENDIFC  200 RETURN      END